if (findings.some(f => f.kind === 'reference-change')) {
    const manifests = require('../scripts/check-manifests.cjs');
    const approvals = manifests.acceptedDecisionText(lib.activeRoot(cwd));
    findings = findings.filter(f => f.kind !== 'reference-change' || !f.edges.length || f.edges.some(e => !manifests.isApprovedEdge(approvals, e.from, e.to)));
  }

function stop(input) {
  if (input.stop_hook_active) return 0; // never re-block a continuation triggered by this hook
  const cochange = require('../scripts/check-cochange.cjs');
  const result = cochange.run(lib.activeRoot(workingDirectory(input)), 'hook');
  if (!result.applicable) {
    process.stdout.write(`${JSON.stringify({ systemMessage: 'Co-change reminders inactive: the project is not a Git work tree.' })}\n`);
    return 0;
  }
  if (!result.reminders.length) return 0;
  process.stderr.write(
    `Co-change reminders (reported once per content state):\n${cochange.format(result.reminders)}\n` +
    'Address each item or state why it does not apply, then finish.\n');
  return 2;
}

function main(event) {
  run(event).then(
    code => {
      process.exitCode = code;
    },
    err => {
      const critical = CRITICAL.has(event);
      process.stderr.write(`[hook ${event}] ${critical ? 'blocked (fail closed)' : 'failed'}: ${err && err.message ? err.message : err}\n`);
      process.exitCode = critical ? 2 : 1;
    });
}

/** Reference-graph findings for one project file: (current Δ base) ∩ (current Δ HEAD), minus recorded approvals. */
function graphFindings(rel, current, base, head, hasHead, approvals, roleOf) {
  const name = path.posix.basename(rel).replace(/\.csproj$/i, '');
  const key = s => s.toLowerCase();
  const cur = new Map((current || []).map(e => [key(e), e]));
  const bas = new Map((base || []).map(e => [key(e), e]));
  const hd = new Map((head || []).map(e => [key(e), e]));
  const changes = [];
  if (current !== null && base === null && (!hasHead || head === null) && roleOf(name).kind !== 'test') {
    if (!manifests.isApprovedProject(approvals, name)) changes.push(`project ${name} added`);
  }
  if (current === null && base !== null && (!hasHead || head !== null) && roleOf(name).kind !== 'test') {
    if (!manifests.isApprovedProject(approvals, name)) changes.push(`project ${name} removed`);
  }
  for (const [k, to] of cur) {
    if (!bas.has(k) && (!hasHead || !hd.has(k)) && !manifests.isApprovedEdge(approvals, name, to)) changes.push(`${name} -> ${to} added`);
  }
  for (const [k, to] of bas) {
    if (!cur.has(k) && (!hasHead || hd.has(k)) && !manifests.isApprovedEdge(approvals, name, to)) changes.push(`${name} -> ${to} removed`);
  }
  if (!changes.length) return [];
  return [lib.finding('error', rel, `project reference graph changed without a recorded approval (Reserved): ${changes.join('; ')}`, OWNER_RESERVED)];
}

let instructionErrors = [];
  if (instructionChanged) {
    instructionErrors = require('./check-instructions.cjs').check(root).filter(f => f.severity === 'error');
